// A tiling desktop: the scene with the focus large on the left, every other scene
// opened in a column beside it, all of them running at once, none over another
// (so each is drawn straight into its part of the panel, at its own pace). A press
// on a tile brings it to the left; its cross closes it; the corners give it the whole desktop
// until pressed again. The bar's + lists the frame's scenes to open.
//
// On a frame that runs one scene at a time (an ESP32, the preview: no
// app.frame.scenes), it is a bar above the scene.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// Drawn, not typed: a font need not have these.
const Glyph = ({ d, color }) => (
  <svg viewBox="0 0 10 10" className="w-[1.8vh] h-[1.8vh] min-w-[8px] min-h-[8px]">
    <path fill="none" stroke={color} strokeWidth="1.4" d={d} />
  </svg>
)
const CLOSE = 'M1.5 1.5L8.5 8.5M8.5 1.5L1.5 8.5'
const GROW = 'M1 4V1H4M6 1H9V4M9 6V9H6M4 9H1V6'
const SHRINK = 'M4 1V4H1M9 4H6V1M6 9V6H9M1 6H4V9'

const openOf = (app) => (Array.isArray(app.state.open) ? app.state.open : [])

const Bar = ({ app, children }) => {
  const now = new Date()
  return (
    <div className={`flex items-center h-[5vh] min-h-[22px] gap-[1vh] px-[1vh] bg-[${app.state.barColor}] text-[${app.state.textColor}] text-[2.6vh]`}>
      {children}
      <span className="font-semibold">{`${pad(now.getHours())}:${pad(now.getMinutes())}`}</span>
    </div>
  )
}

export function get(app) {
  frameos.setNextSleep(60 - new Date().getSeconds())
  const accent = app.state.accent
  const current = app.frame.sceneId
  if (!Array.isArray(app.frame.scenes) || app.frame.systemScene) {
    return (
      <div className="flex flex-col w-full h-full bg-black">
        <Bar app={app}>
          <span className="flex-1 truncate">{app.frame.sceneName}</span>
        </Bar>
        <yield />
      </div>
    )
  }
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (current && !names[current]) names[current] = app.frame.sceneName || current

  // The scene brought forward, however it was, is open; what was open stays.
  const saved = openOf(app)
  const open = saved.filter((id) => names[id])
  let changed = open.length !== saved.length
  if (current && !open.includes(current) && app.state.gone !== current) {
    open.push(current)
    changed = true
  }
  if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
  if (changed) frameos.setState('open', open)

  const focus = (id) => {
    frameos.setState('adding', false)
    if (id !== current) frameos.dispatch('setCurrentScene', { sceneId: id })
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  const close = (id) => {
    const rest = openOf(app).filter((other) => other !== id)
    frameos.setState('open', rest)
    if (id === current) {
      frameos.setState('gone', id)
      frameos.setState('zoomed', false)
      if (rest.length) frameos.dispatch('setCurrentScene', { sceneId: rest[rest.length - 1] })
    }
  }
  const zoomed = on(app.state.zoomed) && open.includes(current)
  const adding = on(app.state.adding)

  const Tile = ({ id, main }) => (
    <div className={`flex flex-col flex-1 min-h-0 min-w-0 border-[0.3vh] ${main ? `border-[${accent}]` : 'border-[#334155]'}`}>
      <div className={`flex items-center h-[3.6vh] min-h-[16px] gap-[1vh] px-[1vh] text-[2.2vh] ${main ? `bg-[${accent}] text-white` : 'bg-[#1e293b] text-[#94a3b8]'}`}>
        <span className="flex-1 truncate">{names[id]}</span>
        {main ? (
          <span className="px-[0.6vh]" onClick={() => frameos.setState('zoomed', !zoomed)}>
            <Glyph d={zoomed ? SHRINK : GROW} color="#ffffff" />
          </span>
        ) : null}
        <span className="px-[0.6vh]" onClick={() => close(id)}>
          <Glyph d={CLOSE} color={main ? '#ffffff' : '#94a3b8'} />
        </span>
      </div>
      <div className="relative flex flex-col flex-1 min-h-0">
        {main ? <yield /> : <Scene id={id} />}
        {main ? null : <div className="absolute inset-0" onPointerDown={() => focus(id)} onClick={() => {}} />}
      </div>
    </div>
  )

  const others = open.filter((id) => id !== current)
  const main = open.includes(current)
  const closed = app.frame.scenes.filter((scene) => !open.includes(scene.id))
  return (
    <div className="relative flex flex-col w-full h-full bg-[#0f172a]">
      <Bar app={app}>
        <span className={`px-[1vh] font-bold ${adding ? 'bg-white/20' : ''}`} onClick={() => frameos.setState('adding', !adding)}>
          +
        </span>
        <div className="flex flex-1 min-w-0 gap-[1vh]">
          {open.map((id) => (
            <span className={`px-[1vh] truncate ${id === current ? `bg-[${accent}] text-white` : 'opacity-70'}`} onClick={() => focus(id)}>
              {names[id]}
            </span>
          ))}
        </div>
      </Bar>
      {zoomed || !others.length ? (
        main ? <Tile id={current} main /> : <div className="flex-1" />
      ) : (
        <div className="flex flex-1 min-h-0">
          {main ? (
            <div className={`flex w-[${others.length ? 60 : 100}%] min-w-0`}>
              <Tile id={current} main />
            </div>
          ) : null}
          <div className="flex flex-col flex-1 min-w-0">
            {others.map((id) => (
              <Tile id={id} />
            ))}
          </div>
        </div>
      )}
      {adding ? (
        <div className="absolute left-[1vh] top-[5vh] flex flex-col min-w-[30vw] bg-[#1e293b] text-white text-[2.6vh] border-[0.3vh] border-[#334155]">
          {closed.length ? (
            closed.map((scene) => (
              <span className="px-[1.5vh] py-[1vh] hover:bg-[#334155]" onClick={() => focus(scene.id)}>
                {scene.name || scene.id}
              </span>
            ))
          ) : (
            <span className="px-[1.5vh] py-[1vh] opacity-60">Every scene is open</span>
          )}
        </div>
      ) : null}
    </div>
  )
}
